const input = $('Chuẩn bị dữ liệu cho AI').first().json;
const ai = $json || {};

const readText = (value) => {
  if (typeof value === 'string') return value;
  if (!value || typeof value !== 'object') return '';
  return String(value.post_content || value.content || value.text || value.body || '').trim();
};

const readOutput = (value) => {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (Array.isArray(value)) {
    return value
      .flatMap((message) => Array.isArray(message?.content) ? message.content : [message])
      .map((part) => part?.text || part?.output_text || '')
      .filter(Boolean)
      .join('\n');
  }
  return String(value || '');
};

let raw = readOutput(ai.output || ai.output_text || ai.response || ai.text);
if (typeof raw === 'string') {
  raw = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

let parsed = raw && typeof raw === 'object' ? raw : null;
if (!parsed && typeof raw === 'string') {
  try {
    parsed = JSON.parse(raw);
  } catch {
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) {
      try { parsed = JSON.parse(match[0]); } catch {}
    }
  }
}

if (!parsed || typeof parsed !== 'object') {
  throw new Error('AI trả về JSON không hợp lệ');
}

const cleanHashtag = (value) => {
  const text = String(value || '').trim().replace(/^#+/, '').replace(/[^\p{L}\p{N}_-]+/gu, '');
  return text ? `#${text}` : '';
};

const getHashtags = (channel, content) => {
  const values = Array.isArray(channel?.hashtags) ? channel.hashtags : [];
  const embedded = String(content || '').match(/#[\p{L}\p{N}_-]+/gu) || [];
  return [...new Set([...values, ...embedded].map(cleanHashtag).filter(Boolean))];
};

const fallbackHashtags = (channel, content) => {
  const hashtags = getHashtags(channel, content);
  const categoryTag = cleanHashtag(input.category);
  const productTag = cleanHashtag(String(input.productName || '').split(/\s+/).slice(0, 2).join(''));
  for (const tag of ['#EPCB', categoryTag, productTag]) {
    if (tag && !hashtags.includes(tag)) hashtags.push(tag);
  }
  return hashtags.slice(0, 5);
};

const formatChannel = (name, limit) => {
  const channel = parsed[name];
  let content = readText(channel);
  if (!content) throw new Error(`AI chưa tạo nội dung ${name}`);

  const hashtags = fallbackHashtags(channel, content);
  if (hashtags.length < 3) throw new Error(`Nội dung ${name} cần ít nhất 3 hashtag`);

  const callToAction = typeof channel === 'object' ? String(channel.call_to_action || channel.callToAction || '').trim() : '';
  if (callToAction && !content.toLowerCase().includes(callToAction.toLowerCase())) {
    content = `${content}\n\n${callToAction}`;
  }
  if (input.sourceUrl && !content.includes(input.sourceUrl)) {
    content = `${content}\n\nXem thêm: ${input.sourceUrl}`;
  }

  const hashtagString = hashtags.join(' ');
  if (!hashtags.every((tag) => content.includes(tag))) {
    content = `${content}\n\n${hashtagString}`;
  }

  const characterCount = content.length;
  if (characterCount > limit) {
    throw new Error(`Nội dung ${name} vượt giới hạn ${limit} ký tự (${characterCount})`);
  }

  return {
    content: content.trim(),
    hashtags,
    characterCount,
    callToAction,
  };
};

const facebook = formatChannel('facebook', 2000);
const linkedin = formatChannel('linkedin', 3000);

return [{
  json: {
    publicationId: input.publicationId,
    facebookContent: facebook.content,
    linkedinContent: linkedin.content,
    quality: {
      facebook: { characterCount: facebook.characterCount, hashtagCount: facebook.hashtags.length },
      linkedin: { characterCount: linkedin.characterCount, hashtagCount: linkedin.hashtags.length },
      checkedAt: new Date().toISOString(),
    },
  },
}];
